import java.util.*;

class Solution {
    public int sharedTrail(String a, String b) {
        int n = a.length(), m = b.length();
        int[] prev = new int[m + 1];          // row i-1 of the table
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];       // row i
            char x = a.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (x == b.charAt(j - 1)) cur[j] = prev[j - 1] + 1;   // both letters join the trail
                else cur[j] = Math.max(prev[j], cur[j - 1]);         // drop one letter
            }
            prev = cur;
        }
        return prev[m];
    }
}

